from pptx import Presentation
from pathlib import Path
from zipfile import ZipFile,BadZipFile
files=[Path('/mnt/data/agent_figures_C_Dossier.pptx'),Path('/mnt/data/agent_figures_C_Dossier_v2.pptx'),Path('/mnt/data/agent_figures_C_Dossier_v2.pdf')]
for f in files:
 print('\n',f.name,'size',f.stat().st_size,'bytes')
 if f.suffix=='.pptx':
  with ZipFile(f) as z:
   print('zip integrity:',z.testzip() or 'OK', 'entries:',len(z.namelist()))
  p=Presentation(f)
  print('slide size (in):',round(p.slide_width/914400,3),round(p.slide_height/914400,3),'slides:',len(p.slides))
  for i,s in enumerate(p.slides,1):
   print(f' Slide {i}: {len(s.shapes)} shapes, text boxes {sum(x.has_text_frame for x in s.shapes)}, picture shapes {sum(x.shape_type==13 for x in s.shapes)}, out-of-bounds={sum(x.left<0 or x.top<0 or x.left+x.width>p.slide_width or x.top+x.height>p.slide_height for x in s.shapes)}')
   if i in [4,5,6]:
    for j,sh in enumerate(s.shapes):
     if sh.has_text_frame and sh.text.strip() and j in [4,5,6]:
      print('   ',j,repr(sh.text[:150]),'bbox',tuple(round(getattr(sh,k)/914400,2) for k in ['left','top','width','height']))
